-- Inventory: suppliers, requests, purchase orders, goods receipt, adjustments, issues, assets, maintenance.
CREATE SEQUENCE public.inv_pr_seq START 236; CREATE SEQUENCE public.inv_po_seq START 421; CREATE SEQUENCE public.inv_grn_seq START 292;
CREATE SEQUENCE public.inv_adj_seq START 72; CREATE SEQUENCE public.inv_iss_seq START 3043; CREATE SEQUENCE public.inv_ast_seq START 13;
CREATE TABLE public.inv_suppliers (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, name VARCHAR(120) NOT NULL, supplies VARCHAR(160) NOT NULL DEFAULT '', gstin VARCHAR(15) NOT NULL DEFAULT '', contact VARCHAR(40) NOT NULL DEFAULT '', status VARCHAR(8) NOT NULL DEFAULT 'Active' CHECK (status IN ('Active', 'Inactive')), UNIQUE (institution_id, name));
CREATE TABLE public.inv_requests (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(12) NOT NULL DEFAULT ('PR-' || lpad(nextval('public.inv_pr_seq')::text, 4, '0')), item_id UUID NOT NULL REFERENCES public.inv_items(id) ON DELETE CASCADE, qty INTEGER NOT NULL CHECK (qty > 0), department VARCHAR(60) NOT NULL DEFAULT '', requested_by VARCHAR(120) NOT NULL DEFAULT '', requested_on DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(16) NOT NULL DEFAULT 'Pending approval' CHECK (status IN ('Pending approval', 'Approved', 'Ordered', 'Rejected')));
CREATE TABLE public.inv_pos (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(12) NOT NULL DEFAULT ('PO-' || lpad(nextval('public.inv_po_seq')::text, 4, '0')), supplier_id UUID NOT NULL REFERENCES public.inv_suppliers(id) ON DELETE CASCADE, raised_on DATE NOT NULL DEFAULT CURRENT_DATE, delivery_by DATE, status VARCHAR(18) NOT NULL DEFAULT 'Pending approval' CHECK (status IN ('Pending approval', 'Sent', 'Partly received', 'Received', 'Rejected')));
CREATE TABLE public.inv_po_lines (po_id UUID NOT NULL REFERENCES public.inv_pos(id) ON DELETE CASCADE, item_id UUID NOT NULL REFERENCES public.inv_items(id) ON DELETE CASCADE, qty INTEGER NOT NULL CHECK (qty > 0), price INTEGER NOT NULL CHECK (price >= 0), received INTEGER NOT NULL DEFAULT 0 CHECK (received >= 0), PRIMARY KEY (po_id, item_id));
CREATE TABLE public.inv_grns (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(12) NOT NULL DEFAULT ('GRN-' || lpad(nextval('public.inv_grn_seq')::text, 4, '0')), po_id UUID REFERENCES public.inv_pos(id) ON DELETE SET NULL, supplier_id UUID REFERENCES public.inv_suppliers(id) ON DELETE SET NULL, received_on DATE NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE public.inv_grn_lines (grn_id UUID NOT NULL REFERENCES public.inv_grns(id) ON DELETE CASCADE, item_id UUID NOT NULL REFERENCES public.inv_items(id) ON DELETE CASCADE, qty INTEGER NOT NULL CHECK (qty > 0), price INTEGER NOT NULL CHECK (price >= 0), PRIMARY KEY (grn_id, item_id));
CREATE TABLE public.inv_adjustments (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(12) NOT NULL DEFAULT ('ADJ-' || lpad(nextval('public.inv_adj_seq')::text, 4, '0')), item_id UUID NOT NULL REFERENCES public.inv_items(id) ON DELETE CASCADE, change INTEGER NOT NULL CHECK (change <> 0), kind VARCHAR(20) NOT NULL, reason VARCHAR(160) NOT NULL DEFAULT '', by_name VARCHAR(120) NOT NULL DEFAULT '', adj_on DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(10) NOT NULL DEFAULT 'Pending' CHECK (status IN ('Pending', 'Approved', 'Rejected')));
CREATE TABLE public.inv_issues (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, code VARCHAR(12) NOT NULL DEFAULT ('ISS-' || nextval('public.inv_iss_seq')), item_id UUID NOT NULL REFERENCES public.inv_items(id) ON DELETE CASCADE, qty INTEGER NOT NULL CHECK (qty > 0), to_kind VARCHAR(12) NOT NULL CHECK (to_kind IN ('Department', 'Staff')), issued_to VARCHAR(80) NOT NULL, person VARCHAR(120) NOT NULL DEFAULT '', issued_on DATE NOT NULL DEFAULT CURRENT_DATE, status VARCHAR(8) NOT NULL DEFAULT 'Issued');
CREATE TABLE public.inv_assets (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, tag VARCHAR(20) NOT NULL DEFAULT ('BG-AST-' || lpad(nextval('public.inv_ast_seq')::text, 4, '0')), name VARCHAR(120) NOT NULL, category VARCHAR(60) NOT NULL DEFAULT '', location VARCHAR(80) NOT NULL DEFAULT 'Main store', custodian VARCHAR(120) NOT NULL DEFAULT '', book_value INTEGER NOT NULL DEFAULT 0 CHECK (book_value >= 0), status VARCHAR(12) NOT NULL DEFAULT 'In store' CHECK (status IN ('In use', 'In store', 'Under repair')), UNIQUE (institution_id, tag));
CREATE TABLE public.inv_maintenance (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(), institution_id UUID NOT NULL REFERENCES public.institutions(id) ON DELETE CASCADE, kind VARCHAR(16) NOT NULL CHECK (kind IN ('Repairs', 'Service schedule')), job VARCHAR(120) NOT NULL, asset VARCHAR(120) NOT NULL DEFAULT '', vendor VARCHAR(100) NOT NULL DEFAULT '', every VARCHAR(30) NOT NULL DEFAULT '', next_due DATE NOT NULL, status VARCHAR(10) NOT NULL DEFAULT 'Scheduled' CHECK (status IN ('Scheduled', 'Done')));
ALTER TABLE public.inv_suppliers ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inv_requests ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inv_pos ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inv_po_lines ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inv_grns ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inv_grn_lines ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inv_adjustments ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inv_issues ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inv_assets ENABLE ROW LEVEL SECURITY; ALTER TABLE public.inv_maintenance ENABLE ROW LEVEL SECURITY;
